from typing import Dict, Union, Any
import re
import os
import sys

# Add parent directory to path for imports when run as standalone script
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from utils.validation_parser import (
    check_tool_called,
    is_validation_successful,
)


def validate_graphql_blocks(
    output: str, context: Dict[str, Any]
) -> Dict[str, Union[bool, float, str]]:
    # This extraction logic needs to stay because we have golden prompts that
    # Will not produce any GraphQL blocks for admin. We should probably not have this assertion at all for prompts
    # that don't expect GraphQL blocks to be generated.
    graphql_regex = re.compile(
        r"```graphql?\s*((?:query|mutation).*?)```", re.DOTALL | re.MULTILINE
    )
    matches = graphql_regex.findall(output)

    tool_name = "validate_graphql_codeblocks"

    if not matches:
        return {"pass": True, "score": 1.0, "reason": "No GraphQL blocks found."}

    # Check if the tool was called
    if not check_tool_called(output, tool_name):
        return {
            "pass": False,
            "score": 0.0,
            "reason": f"GraphQL blocks found but {tool_name} tool was not called.",
        }

    # Check if validation was successful
    if is_validation_successful(output, tool_name):
        return {
            "pass": True,
            "score": 1.0,
            "reason": "GraphQL blocks found and validated.",
        }

    # Validation was called but failed
    return {
        "pass": False,
        "score": 0.0,
        "reason": f"GraphQL blocks found but {tool_name} validation failed.",
    }


def get_assert(output: str, context: Dict[str, Any]) -> Dict[str, Any]:
    return validate_graphql_blocks(output, context)
